insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$campo-do-tenente$q$, $q$https://www.diariomunicipal.com.br/amp/materia/2E0C4AAF (Decreto 108/2019) ; https://www.diariomunicipal.com.br/amp/materia/C79427D2 (Decreto 237/2013) ; https://www.diariomunicipal.com.br/amp/materia/BE8A97E9 (Lei 971/2019)$q$, $q$Atos oficiais do município: domínio público (Lei 9.610/1998 art. 8º IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OSM). Texto obtido no Diário Oficial dos Municípios do Paraná (AMP).$q$, 5, $q$Só o Decreto 108/2019 (PBT > 30 t nas Ruas Olívio Belich e Augustinho Tiburski) é ativo. O Decreto 237/2013 (Serrinha, > 7 t) e a Lei 971/2019 (estradas rurais em dia de chuva) entram desativados.$q$);
